// Neural Geometry Constructor for "Mechanism" ⚙️ #WCCChallenge"


/** A generative machine that constructs an evolving neural geometry system in real time. 
	Inspired by robotic plotters, architectural drafting systems, and graph intelligence, 
	the mechanism moves across a blueprint-like space, stamping nodes, forming weighted connections, 
	and assembling dynamic triangulated structures that resemble an autonomous thinking network.
**/

let nodes = [];
let edges = [];
let triangles = [];
let machine;
let target;
let buildTimer = 0;

function setup() {
  createCanvas(windowWidth, windowHeight);
  strokeCap(ROUND);
  machine = new Machine();
  chooseTarget();
}

function draw() {
  background(8, 10, 14);

  drawBlueprintGrid();
  drawConstructedGeometry();

  machine.update();
  machine.display();

  buildTimer++;

  if (dist(machine.head.x, machine.head.y, target.x, target.y) < 5 && buildTimer > 18) {
    stampNode(target.x, target.y);
    chooseTarget();
    buildTimer = 0;
  }
}

function chooseTarget() {
  let margin = 120;

  if (nodes.length === 0) {
    target = createVector(width * 0.5, height * 0.58);
  } else {
    let parent = random(nodes);
    let angle = random(TWO_PI);
    let radius = random(55, 135);

    target = createVector(
      constrain(parent.x + cos(angle) * radius, margin, width - margin),
      constrain(parent.y + sin(angle) * radius, margin, height - margin)
    );
  }

  machine.setTarget(target);
}

function stampNode(x, y) {
  let node = {
    x,
    y,
    r: random(4, 8),
    age: 0,
    pulse: 1
  };

  nodes.push(node);

  let nearest = nodes
    .filter(n => n !== node)
    .sort((a, b) => dist(a.x, a.y, x, y) - dist(b.x, b.y, x, y))
    .slice(0, 3);

  for (let n of nearest) {
    edges.push({
      a: node,
      b: n,
      age: 0,
      weight: random(0.4, 1.2)
    });
  }

  if (nearest.length >= 2) {
    triangles.push({
      a: node,
      b: nearest[0],
      c: nearest[1],
      age: 0
    });
  }

  if (nodes.length > 90) {
    nodes.shift();
    edges = edges.filter(e => nodes.includes(e.a) && nodes.includes(e.b));
    triangles = triangles.filter(t => nodes.includes(t.a) && nodes.includes(t.b) && nodes.includes(t.c));
  }
}

class Machine {
  constructor() {
    this.railY = 70;
    this.carriage = createVector(width * 0.5, this.railY);
    this.head = createVector(width * 0.5, height * 0.5);
    this.target = createVector(width * 0.5, height * 0.5);
  }

  setTarget(v) {
    this.target = v.copy();
  }

  update() {
    this.carriage.x = lerp(this.carriage.x, this.target.x, 0.045);
    this.head.x = lerp(this.head.x, this.target.x, 0.055);
    this.head.y = lerp(this.head.y, this.target.y, 0.055);
  }

  display() {
    // rail
    stroke(210, 220, 230, 95);
    strokeWeight(3);
    line(70, this.railY, width - 70, this.railY);

    // rail ticks
    stroke(210, 220, 230, 35);
    strokeWeight(1);
    for (let x = 90; x < width - 90; x += 35) {
      line(x, this.railY - 8, x, this.railY + 8);
    }

    // carriage
    noStroke();
    fill(210, 220, 230, 190);
    rectMode(CENTER);
    rect(this.carriage.x, this.railY, 46, 22, 4);

    // vertical actuator
    stroke(210, 220, 230, 70);
    strokeWeight(2);
    line(this.carriage.x, this.railY + 12, this.head.x, this.head.y);

    // articulated arms
    let mid1 = createVector(
      lerp(this.carriage.x, this.head.x, 0.45) + sin(frameCount * 0.04) * 25,
      lerp(this.railY, this.head.y, 0.45)
    );

    stroke(235, 240, 245, 150);
    strokeWeight(4);
    line(this.carriage.x, this.railY + 12, mid1.x, mid1.y);
    line(mid1.x, mid1.y, this.head.x, this.head.y);

    noStroke();
    fill(240, 245, 250, 220);
    circle(mid1.x, mid1.y, 9);

    // drawing head glow
    fill(120, 190, 255, 40);
    circle(this.head.x, this.head.y, 34);

    fill(160, 215, 255, 230);
    circle(this.head.x, this.head.y, 9);

    // laser / construction point
    stroke(120, 190, 255, 90);
    strokeWeight(1.5);
    line(this.head.x, this.head.y, target.x, target.y);
  }
}

function drawConstructedGeometry() {
  for (let t of triangles) {
    t.age++;
    let a = constrain(t.age * 3, 0, 38);

    noStroke();
    fill(90, 150, 210, a * 0.35);
    triangle(t.a.x, t.a.y, t.b.x, t.b.y, t.c.x, t.c.y);

    stroke(120, 180, 240, a);
    strokeWeight(0.8);
    noFill();
    triangle(t.a.x, t.a.y, t.b.x, t.b.y, t.c.x, t.c.y);
  }

  for (let e of edges) {
    e.age++;
    let a = constrain(e.age * 4, 0, 150);
    let shimmer = sin(frameCount * 0.05 + e.weight * 4) * 0.5 + 0.5;

    stroke(220, 235, 245, a);
    strokeWeight(0.8 + e.weight + shimmer);
    line(e.a.x, e.a.y, e.b.x, e.b.y);
  }

  for (let n of nodes) {
    n.age++;
    n.pulse *= 0.92;

    noStroke();
    fill(120, 190, 255, 45 * n.pulse);
    circle(n.x, n.y, 28 * n.pulse);

    fill(235, 240, 245, constrain(n.age * 8, 0, 230));
    circle(n.x, n.y, n.r);
  }
}

function drawBlueprintGrid() {
  stroke(255, 255, 255, 9);
  strokeWeight(1);

  for (let x = 0; x < width; x += 40) {
    line(x, 0, x, height);
  }

  for (let y = 0; y < height; y += 40) {
    line(0, y, width, y);
  }

  stroke(120, 190, 255, 20);
  line(0, height * 0.58, width, height * 0.58);
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
  machine = new Machine();
  nodes = [];
  edges = [];
  triangles = [];
  chooseTarget();
}

// 1. 免疫 DOM 元素建立導致的看門狗攔截
if (typeof createP === 'undefined') { window.createP = function() { return { position: function(){}, style: function(){} }; }; }
if (typeof createDiv === 'undefined') { window.createDiv = function() { return { position: function(){}, style: function(){} }; }; }

// 2. 圖片與非同步資產載入後備自癒護欄
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origLoadImage === 'undefined') { window._origLoadImage = p5.prototype.loadImage; }
    p5.prototype.loadImage = function(path, successCallback, failureCallback) {
        if (typeof path !== 'string' || (path.startsWith('http') === false && path.startsWith('data:') === false)) {
            // 當發現是相對路徑或丟失的外部圖片資產時，使用 1x1 灰色 GIF 的 Base64 代替，防止渲染死鎖
            const dummyPath = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
            return window._origLoadImage.call(this, dummyPath, successCallback, failureCallback);
        }
        return window._origLoadImage.call(this, path, successCallback, failureCallback);
    };
}

// 3. 修正 3D 渲染圖層 WebGL 與 Canvas 2D 上下文屬性缺失
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origGet === 'undefined') { window._origGet = p5.prototype.get; }
    p5.prototype.get = function(...args) {
        if (this.width === 0 || this.height === 0) {
            return createGraphics(10, 10);
        }
        return window._origGet.apply(this, args);
    };
}
